// Validates the SEARCH_INDEX_PLAN §4.1 normalization against REAL PlantUmlCreator output
// (generated by formatter-probe). Every assertion documents a rule; a FAIL means the rule
// as specced does not reconstruct what the user sees rendered.
'use strict';
const fs = require('fs');
const path = require('path');

const raw = fs.readFileSync(path.join(__dirname, 'formatter-output', 'stress-0.puml'), 'utf8');

// §4.1 normalization — reference implementation lives in normalize.js (shared with m1-bench.js)
const { normalizeForSearch } = require('./normalize');

const norm = normalizeForSearch(raw);
const longToken = ('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.' + 'A'.repeat(60)
  + 'NEEDLE-RUNWRAP-7f3a9c2e' + 'B'.repeat(60) + '.sig-' + 'C'.repeat(60)).toLowerCase();
const longHeader = ('chunkstart-' + 'h'.repeat(100) + 'NEEDLE-HDRCHUNK-42' + 'k'.repeat(100) + '-chunkend').toLowerCase();
const longPath = ('/orders/' + 'p'.repeat(130) + 'NEEDLE-URLPATH-3').toLowerCase();
const urlRun = ('filter=' + 'q'.repeat(90) + 'NEEDLE-URLRUN-9&page=2').toLowerCase();

let pass = 0, fail = 0;
function check(label, cond, extra) {
  console.log((cond ? 'PASS' : 'FAIL') + '  ' + label + (extra && !cond ? '  [' + extra + ']' : ''));
  cond ? pass++ : fail++;
}

check('raw does NOT contain the wrapped blob contiguously (proves the wrap fired)', !raw.toLowerCase().includes(longToken));
check('rule 5b rejoins 120-char run wrapping: full 200+ char token contiguous', norm.includes(longToken));
check('rules 4+5b rejoin 80-char gray header chunking: full header value contiguous', norm.includes(longHeader));
check('rule 3 unescapes creole: **important** and //slanted// plus __deep__', norm.includes('**important** and //slanted// plus __deep__'));
check('rule 5a rejoins arrow-label \\n escape: full URL path contiguous', norm.includes(longPath));
check('rule 5b rejoins wrapped URL inside JSON value', norm.includes(urlRun));
check('documented limitation: null property stripped by formatter (not findable)', !norm.includes('nullfield'));
check('unicode payload text survives untouched (İstanbul, ASCII-fold leaves İ alone)', norm.includes('İstanbul'.replace(/[A-Z]/g, c => c.toLowerCase())));
check('ordinary sentence with spaces unharmed', norm.includes('a perfectly ordinary sentence with spaces so it wraps normally'));
check('structural note boundary survives (end note not glued into payload)', /\n\s*end note/.test(norm));

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
